describe('Search Field Dropdown Matching Options', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should display matching options as user types in search field', () => {
    // Setup: intercept the API call for search
    cy.intercept('GET', '/api/search*', (req) => {
      req.reply((res) => {
        res.body = {
          results: [
            { id: 1, name: 'Apple' },
            { id: 2, name: 'Banana' },
            { id: 3, name: 'Cherry' },
            { id: 4, name: 'Date' },
            { id: 5, name: 'Elderberry' },
          ]
        };
      });
    }).as('searchResults');

    // Verify search input is visible
    cy.get('[data-testid="search-input"]').should('be.visible');

    // Type in search field to trigger dropdown
    cy.get('[data-testid="search-input"]').type('a');

    // Wait for API call
    cy.wait('@searchResults');

    // Verify dropdown appears
    cy.get('[data-testid="search-dropdown"]').should('be.visible');

    // Verify first matching option is displayed
    cy.get('[data-testid="search-dropdown"]').should('contain', 'Apple');

    // Verify dropdown contains all matching options
    cy.get('[data-testid="search-dropdown"]').should('contain', 'Banana');
    cy.get('[data-testid="search-dropdown"]').should('contain', 'Cherry');
    cy.get('[data-testid="search-dropdown"]').should('contain', 'Date');
    cy.get('[data-testid="search-dropdown"]').should('contain', 'Elderberry');

    // Verify dropdown has correct number of options
    cy.get('[data-testid="search-dropdown"]').should('have.length', 5);

    // Verify dropdown is not empty when no matches
    cy.get('[data-testid="search-input"]').type('zzz');
    cy.wait('@searchResults');
    cy.get('[data-testid="search-dropdown"]').should('contain', 'No results found');

    // Verify dropdown is empty when no matches
    cy.get('[data-testid="search-dropdown"]').should('not.exist');
  });

  it('should handle empty search input and display no results message', () => {
    // Verify search input is visible
    cy.get('[data-testid="search-input"]').should('be.visible');

    // Clear search input
    cy.get('[data-testid="search-input"]').clear();

    // Verify no results message is displayed
    cy.get('[data-testid="no-results-message"]').should('be.visible');

    // Verify no results message contains expected text
    cy.get('[data-testid="no-results-message"]').should('contain', 'No results found');

    // Verify search dropdown is not visible
    cy.get('[data-testid="search-dropdown"]').should('not.exist');
  });
});
